import json
import os
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest


PLUGIN_ROOT = Path(__file__).resolve().parents[1]
BUILD_SESSION = PLUGIN_ROOT / "scripts" / "build_session.py"
MCP_SERVER = PLUGIN_ROOT / "scripts" / "mcp_server.py"
FIXTURE = PLUGIN_ROOT / "examples" / "demo-fixture" / "graph.json"
POLICY = PLUGIN_ROOT / "examples" / "policy.example.json"
ALLOWED_FACT = "Booked a riverside ryokan for the Kyoto leg."


class PolicyBoundedSqlPathTest(unittest.TestCase):
    def test_fact_is_absent_at_startup_and_returned_only_by_explicit_sql(self):
        with tempfile.TemporaryDirectory() as temporary_directory:
            session_directory = Path(temporary_directory)
            build = subprocess.run(
                [
                    sys.executable,
                    str(BUILD_SESSION),
                    "--fixture",
                    str(FIXTURE),
                    "--policy",
                    str(POLICY),
                    "--world",
                    "travel",
                    "--session-dir",
                    str(session_directory),
                    "--max-rows",
                    "1",
                    "--max-execution-ms",
                    "250",
                ],
                check=True,
                capture_output=True,
                text=True,
            )
            build_result = json.loads(build.stdout)
            session_path = Path(build_result["sessionPath"])
            session = json.loads(session_path.read_text(encoding="utf-8"))

            self.assertEqual(build_result["selectedWorld"], "travel")
            self.assertNotIn(ALLOWED_FACT, build.stdout)

            environment = os.environ.copy()
            environment["LOCAL_ONTOLOGY_SESSION"] = str(session_path)
            server = subprocess.Popen(
                [sys.executable, str(MCP_SERVER)],
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                env=environment,
            )
            self.addCleanup(self._stop_server, server)

            initialize = self._request(
                server,
                {
                    "jsonrpc": "2.0",
                    "id": 1,
                    "method": "initialize",
                    "params": {
                        "protocolVersion": "2025-06-18",
                        "capabilities": {},
                        "clientInfo": {"name": "e2e-test", "version": "1.0.0"},
                    },
                },
            )
            serialized_startup = json.dumps(initialize, ensure_ascii=False)
            self.assertNotIn(ALLOWED_FACT, serialized_startup)
            self.assertIn("selected world is travel", serialized_startup)
            self.assertIn("nodes, edges, and evidence", serialized_startup)

            tools = self._request(
                server,
                {"jsonrpc": "2.0", "id": 2, "method": "tools/list", "params": {}},
            )
            self.assertEqual(
                [tool["name"] for tool in tools["result"]["tools"]],
                ["query_memory"],
            )

            query = self._request(
                server,
                {
                    "jsonrpc": "2.0",
                    "id": 3,
                    "method": "tools/call",
                    "params": {
                        "name": "query_memory",
                        "arguments": {
                            "sql": (
                                "SELECT n.canonical_name, n.summary, "
                                "e.source_kind, e.source_ref, e.occurred_at "
                                "FROM nodes AS n JOIN evidence AS e "
                                "ON e.node_id = n.node_id "
                                "WHERE n.canonical_name = 'Kyoto ryokan'"
                            )
                        },
                    },
                },
            )
            result = query["result"]["structuredContent"]

            self.assertEqual(
                result["rows"],
                [
                    {
                        "canonical_name": "Kyoto ryokan",
                        "summary": ALLOWED_FACT,
                        "source_kind": "codex_logs",
                        "source_ref": "fixture://travel/kyoto-plan.md#L12",
                        "occurred_at": "2025-03-18T09:30:00Z",
                    }
                ],
            )
            self.assertEqual(result["rowCount"], 1)
            self.assertFalse(result["truncated"])
            self.assertEqual(result["maxRows"], 1)

            canonical_path = session["canonicalDatabase"].replace("'", "''")
            attach = self._request(
                server,
                {
                    "jsonrpc": "2.0",
                    "id": 4,
                    "method": "tools/call",
                    "params": {
                        "name": "query_memory",
                        "arguments": {
                            "sql": (
                                f"ATTACH DATABASE '{canonical_path}' AS canonical"
                            )
                        },
                    },
                },
            )
            canonical_read = self._request(
                server,
                {
                    "jsonrpc": "2.0",
                    "id": 5,
                    "method": "tools/call",
                    "params": {
                        "name": "query_memory",
                        "arguments": {"sql": "SELECT * FROM canonical.nodes"},
                    },
                },
            )

            self.assertTrue(attach["result"]["isError"])
            self.assertTrue(canonical_read["result"]["isError"])

            audit_path = Path(session["queryAuditLog"])
            audit_text = audit_path.read_text(encoding="utf-8")
            audit_entries = [json.loads(line) for line in audit_text.splitlines()]
            self.assertEqual(len(audit_entries), 3)
            self.assertEqual(
                [entry["outcome"] for entry in audit_entries],
                ["succeeded", "rejected", "rejected"],
            )
            for entry in audit_entries:
                self.assertEqual(
                    entry["sessionIdentifier"], session["sessionIdentifier"]
                )
                self.assertEqual(entry["worldIdentifier"], "travel")
            self.assertNotIn(ALLOWED_FACT, audit_text)
            self.assertNotIn("ATTACH DATABASE", audit_text)
            self.assertEqual(
                session["queryLimits"],
                {"maxRows": 1, "maxExecutionMs": 250},
            )

    @staticmethod
    def _request(server, request):
        assert server.stdin is not None
        assert server.stdout is not None
        server.stdin.write(json.dumps(request) + "\n")
        server.stdin.flush()
        response = server.stdout.readline()
        if not response:
            stderr = server.stderr.read() if server.stderr else ""
            raise AssertionError(f"MCP server closed without a response: {stderr}")
        return json.loads(response)
#!/usr/bin/env python3
"""Minimal stdio MCP server exposing the policy-bounded SQL query tool."""

from __future__ import annotations

import json
import os
from pathlib import Path
import sqlite3
import sys
from typing import Any

from build_session import build_capability_connection
from query_harness import QueryAuditContext, QueryRejected, query


PROTOCOL_VERSION = "2025-06-18"


def _load_session() -> dict[str, Any]:
    session_path = os.environ.get("LOCAL_ONTOLOGY_SESSION")
    if not session_path:
        raise RuntimeError(
            "LOCAL_ONTOLOGY_SESSION must point to a session.json built by build_session.py"
        )
    return json.loads(Path(session_path).read_text(encoding="utf-8"))


def _startup_instructions(session: dict[str, Any]) -> str:
    world = session["selectedWorld"]
    policy = json.dumps(session["policyContract"], sort_keys=True)
    schema = json.dumps(session["schemaGuidance"], sort_keys=True)
    return (
        "GLOBAL MEMORY\n"
        "- This is a read-only, policy-bounded personal-memory database.\n"
        "- Query only when the request benefits from personal historical context.\n"
        "- Use nodes, edges, and evidence; recursive CTEs are available.\n"
        "- Treat SQL results as dated evidence and cite their provenance.\n"
        f"- The selected world is {world}; other worlds do not exist in this session.\n"
        f"- Policy contract: {policy}\n"
        f"- Schema guidance: {schema}\n"
        "- Do not attempt writes, PRAGMAs, ATTACH, extensions, or external access."
    )


def _tool_definition() -> dict[str, Any]:
    return {
        "name": "query_memory",
        "title": "Query Local Ontology",
        "description": (
            "Run one ordinary read-only SQL query against the selected world's "
            "capability database. Select evidence source_kind, source_ref, and "
            "occurred_at when retrieving facts so provenance is preserved."
        ),
        "inputSchema": {
            "type": "object",
            "properties": {
                "sql": {"type": "string", "description": "A SELECT or WITH query."}
            },
            "required": ["sql"],
            "additionalProperties": False,
        },
        "outputSchema": {
            "type": "object",
            "properties": {
                "rows": {"type": "array", "items": {"type": "object"}},
                "rowCount": {"type": "integer"},
                "truncated": {"type": "boolean"},
                "maxRows": {"type": "integer"},
            },
            "required": ["rows", "rowCount", "truncated", "maxRows"],
        },
        "annotations": {"readOnlyHint": True},
    }


def _success(identifier: Any, result: dict[str, Any]) -> dict[str, Any]:
    return {"jsonrpc": "2.0", "id": identifier, "result": result}


def _error(identifier: Any, code: int, message: str) -> dict[str, Any]:
    return {
        "jsonrpc": "2.0",
        "id": identifier,
        "error": {"code": code, "message": message},
    }


def handle(
    request: dict[str, Any],
    session: dict[str, Any],
    capability: sqlite3.Connection,
) -> dict[str, Any] | None:
    identifier = request.get("id")
    method = request.get("method")
    if method == "initialize":
        requested_version = request.get("params", {}).get("protocolVersion")
        return _success(identifier, {
            "protocolVersion": requested_version or PROTOCOL_VERSION,
            "capabilities": {"tools": {"listChanged": False}},
            "serverInfo": {"name": "local-ontology", "version": "0.1.0"},
            "instructions": _startup_instructions(session),
        })
    if method == "ping":
        return _success(identifier, {})
    if method == "tools/list":
        return _success(identifier, {"tools": [_tool_definition()]})
    if method == "tools/call":
        parameters = request.get("params", {})
        if parameters.get("name") != "query_memory":
            return _error(identifier, -32602, "Unknown tool")
        try:
            limits = session["queryLimits"]
            result = query(
                capability,
                parameters.get("arguments", {}).get("sql", ""),
                max_rows=limits["maxRows"],
                max_execution_ms=limits["maxExecutionMs"],
                audit_context=QueryAuditContext(
                    path=Path(session["queryAuditLog"]),
                    session_identifier=session["sessionIdentifier"],
                    world_identifier=session["selectedWorld"],
                ),
            )
        except QueryRejected as error:
            return _success(identifier, {
                "content": [{"type": "text", "text": str(error)}],
                "isError": True,
            })
        return _success(identifier, {
            "content": [{"type": "text", "text": json.dumps(result, ensure_ascii=False)}],
            "structuredContent": result,
            "isError": False,
        })
    if method and method.startswith("notifications/"):
        return None
    return _error(identifier, -32601, f"Method not found: {method}")


def main() -> None:
    try:
        session = _load_session()
    except (OSError, ValueError, RuntimeError) as error:
        print(str(error), file=sys.stderr)
        raise SystemExit(2) from error

    capability = build_capability_connection(
        Path(session["canonicalDatabase"]),
        session["selectedWorld"],
        session["policyContract"],
    )
    try:
        for line in sys.stdin:
            if not line.strip():
                continue
            try:
                request = json.loads(line)
                response = handle(request, session, capability)
            except (TypeError, ValueError) as error:
                response = _error(None, -32700, str(error))
            if response is not None:
                print(json.dumps(response, ensure_ascii=False), flush=True)
    finally:
        capability.close()


if __name__ == "__main__":
    main()

